import React from 'react';
import {
    Card,
    CardContent,
    Typography,
    Box,
    LinearProgress,
    Grid,
    Tooltip,
    Skeleton,
} from '@mui/material';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import { formatPercentage } from '../../utils/formatters';

interface MetricItem {
    name: string;
    value: number;
    description: string;
    color: string;
}

interface ModelMetricsProps {
    metrics?: {
        accuracy: number;
        mae: number;
        rmse: number;
        r2_score: number;
    };
    loading?: boolean;
}

const ModelMetrics: React.FC<ModelMetricsProps> = ({ metrics, loading = false }) => {
    const metricsList: MetricItem[] = [
        {
            name: 'Accuracy',
            value: metrics?.accuracy || 0,
            description: 'Overall model prediction accuracy',
            color: '#0D63F4',
        },
        {
            name: 'R² Score',
            value: metrics?.r2_score || 0,
            description: 'Coefficient of determination (goodness of fit)',
            color: '#16A34A',
        },
        {
            name: 'MAE',
            value: metrics?.mae ? 1 - metrics.mae / 100 : 0,
            description: 'Mean Absolute Error (lower is better)',
            color: '#F59E0B',
        },
        {
            name: 'RMSE',
            value: metrics?.rmse ? 1 - metrics.rmse / 100 : 0,
            description: 'Root Mean Square Error (lower is better)',
            color: '#DC2626',
        },
    ];

    if (loading) {
        return (
            <Card>
                <CardContent>
                    <Skeleton variant="text" width="40%" height={32} />
                    <Skeleton variant="rectangular" width="100%" height={200} sx={{ mt: 2, borderRadius: 2 }} />
                </CardContent>
            </Card>
        );
    }

    return (
        <Card>
            <CardContent sx={{ p: 3 }}>
                <Typography variant="h5" fontWeight={700} gutterBottom>
                    Model Performance
                </Typography>
                <Typography variant="body2" color="text.secondary" mb={3}>
                    Key metrics for forecast model evaluation
                </Typography>

                <Grid container spacing={3}>
                    {metricsList.map((metric, index) => (
                        <Grid item xs={12} sm={6} key={index}>
                            <Box>
                                <Box display="flex" justifyContent="space-between" alignItems="center" mb={1}>
                                    <Box display="flex" alignItems="center" gap={0.5}>
                                        <Typography variant="body2" fontWeight={700}>
                                            {metric.name}
                                        </Typography>
                                        <Tooltip title={metric.description} arrow placement="top">
                                            <InfoOutlinedIcon
                                                sx={{
                                                    fontSize: 16,
                                                    color: 'text.secondary',
                                                    cursor: 'help',
                                                }}
                                            />
                                        </Tooltip>
                                    </Box>
                                    <Typography variant="h6" fontWeight={700} color={metric.color}>
                                        {formatPercentage(metric.value, 1)}
                                    </Typography>
                                </Box>
                                <LinearProgress
                                    variant="determinate"
                                    value={metric.value * 100}
                                    sx={{
                                        height: 8,
                                        borderRadius: 4,
                                        backgroundColor: 'grey.200',
                                        '& .MuiLinearProgress-bar': {
                                            backgroundColor: metric.color,
                                            borderRadius: 4,
                                        },
                                    }}
                                />
                            </Box>
                        </Grid>
                    ))}
                </Grid>

                <Box
                    sx={{
                        mt: 3,
                        p: 2,
                        backgroundColor: 'grey.50',
                        borderRadius: 2,
                        border: '1px solid',
                        borderColor: 'divider',
                    }}
                >
                    <Typography variant="caption" color="text.secondary" fontWeight={600}>
                        💡 Model Performance Insights
                    </Typography>
                    <Typography variant="body2" color="text.secondary" mt={1}>
                        The model demonstrates {metrics?.accuracy && metrics.accuracy > 0.9 ? 'excellent' : 'good'} predictive
                        performance with an accuracy of {formatPercentage(metrics?.accuracy || 0)}. Regular
                        retraining ensures optimal forecast precision.
                    </Typography>
                </Box>
            </CardContent>
        </Card>
    );
};

export default ModelMetrics;
